{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "nativeFamily",
    "liveRows",
    "system",
    "grants",
    "cold",
    "cancel",
    "box"
  ],
  "properties": {
    "version": {
      "const": 1
    },
    "nativeFamily": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "handoffCapacityBytes",
        "handoffReleaseBytes",
        "convertToNurbs",
        "wire",
        "compoundVolume"
      ],
      "properties": {
        "handoffCapacityBytes": {
          "const": 0
        },
        "handoffReleaseBytes": {
          "const": 0
        },
        "convertToNurbs": {
          "const": [
            false,
            true
          ]
        },
        "wire": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "width",
            "height",
            "length"
          ],
          "properties": {
            "width": {
              "const": 2
            },
            "height": {
              "const": 3
            },
            "length": {
              "const": 10
            }
          }
        },
        "compoundVolume": {
          "const": 2
        }
      }
    },
    "liveRows": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "keys",
        "removedKeys",
        "payloadBytes",
        "maximumPredicatesPerTurn",
        "extractionCapacityBytes",
        "extractionReleaseBytes"
      ],
      "properties": {
        "keys": {
          "const": [
            "a",
            "b",
            "c",
            "d"
          ]
        },
        "removedKeys": {
          "const": [
            "a",
            "c"
          ]
        },
        "payloadBytes": {
          "const": 17
        },
        "maximumPredicatesPerTurn": {
          "const": 1
        },
        "extractionCapacityBytes": {
          "const": 0
        },
        "extractionReleaseBytes": {
          "const": 0
        }
      }
    },
    "system": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "constructorCapacityBytes",
        "cancelCapacityBytes",
        "cancelReleaseBytes",
        "handoffCapacityBytes",
        "handoffReleaseBytes",
        "turnCapacityBytes"
      ],
      "properties": {
        "constructorCapacityBytes": {
          "const": 0
        },
        "cancelCapacityBytes": {
          "const": 0
        },
        "cancelReleaseBytes": {
          "const": 0
        },
        "handoffCapacityBytes": {
          "const": 0
        },
        "handoffReleaseBytes": {
          "const": 0
        },
        "turnCapacityBytes": {
          "const": 0
        }
      }
    },
    "grants": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "items",
        "bytes"
      ],
      "properties": {
        "items": {
          "const": 1
        },
        "bytes": {
          "const": 8
        }
      }
    },
    "cold": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "initialEdges",
        "initialFaces",
        "initialUnits",
        "callerProbeTurns"
      ],
      "properties": {
        "initialEdges": {
          "const": 0
        },
        "initialFaces": {
          "const": 0
        },
        "initialUnits": {
          "const": 0
        },
        "callerProbeTurns": {
          "const": 8
        }
      }
    },
    "cancel": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "releasesAtSignal",
        "releasesBeforeCredit",
        "sampleReleases",
        "meshReleases"
      ],
      "properties": {
        "releasesAtSignal": {
          "const": 0
        },
        "releasesBeforeCredit": {
          "const": 0
        },
        "sampleReleases": {
          "const": 1
        },
        "meshReleases": {
          "const": 1
        }
      }
    },
    "box": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "faces",
        "edges",
        "triangles",
        "area",
        "volume"
      ],
      "properties": {
        "faces": {
          "const": 6
        },
        "edges": {
          "const": 12
        },
        "triangles": {
          "const": 12
        },
        "area": {
          "const": 6
        },
        "volume": {
          "const": 1
        }
      }
    }
  }
}
